def reachable(p):
    n=len(p)
    comp=[[False]*n for _ in range(n)]
    for i in range(n):
      for j in range(n):
        if i<j and p[i]<p[j]: comp[i][j]=comp[j][i]=True
    # antichains S any subset pairwise incomparable
    Fs={tuple([1]*n)}
    idx=range(n)
    for r in range(1,n+1):
      for S in itertools.combinations(idx,r):
        ok=True
        for a,b in itertools.combinations(S,2):
          if comp[a][b]: ok=False;break
        if not ok: continue
        alive=[1]*n
        for k in S:
          for i in idx:
            if i!=k and comp[i][k]: alive[i]=0
        Fs.add(tuple(alive))
    return Fs

