import sys

MOD = 998244353


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N - 1)]

    # SPF up to 1000
    M = 1000
    spf = list(range(M + 1))
    for i in range(2, int(M ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, M + 1, i):
                if spf[j] == j:
                    spf[j] = i

    exps = {}  # p -> list of v_p(A_i)
    for idx, a in enumerate(A):
        x = a
        while x > 1:
            p = spf[x]
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            arr = exps.get(p)
            if arr is None:
                arr = [0] * (N - 1)
                exps[p] = arr
            arr[idx] = c

    ans = 1

    for p, d in exps.items():
        D = sum(d)
        if D == 0:
            continue

        powp = [1] * (D + 1)
        for i in range(1, D + 1):
            powp[i] = (powp[i - 1] * p) % MOD

        def calc(B: int) -> int:
            # Sum of weights for sequences x_1..x_N with 0<=x_i<=B and |x_i-x_{i+1}|=d_i
            dp = powp[:B + 1]  # i=1, weight p^{x1}

            for delta in d:
                nd = [0] * (B + 1)
                if delta == 0:
                    for u in range(B + 1):
                        nd[u] = (dp[u] * powp[u]) % MOD
                else:
                    bd = B - delta

                    lim = delta
                    if lim > B + 1:
                        lim = B + 1
                    # u in [0, lim-1]: only source u+delta
                    for u in range(lim):
                        v = u + delta
                        if v <= B:
                            nd[u] = (dp[v] * powp[u]) % MOD

                    # u in [delta, bd]: both sources
                    l = delta
                    r = bd
                    if l <= r:
                        for u in range(l, r + 1):
                            nd[u] = ((dp[u - delta] + dp[u + delta]) * powp[u]) % MOD

                    # u in [max(delta, bd+1), B]: only source u-delta
                    start = delta
                    t = bd + 1
                    if start < t:
                        start = t
                    for u in range(start, B + 1):
                        nd[u] = (dp[u - delta] * powp[u]) % MOD

                dp = nd

            s = 0
            for v in dp:
                s += v
            return s % MOD

        total_nonneg = calc(D)
        total_pos = calc(D - 1)  # via shift x_i = y_i + 1
        gp = (total_nonneg - pow(p, N, MOD) * total_pos) % MOD

        ans = (ans * gp) % MOD

    print(ans)


