import sys

def main() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    A = data[1:1 + n]
    m = max(A)

    # Smallest prime factor sieve
    spf = list(range(m + 1))
    for i in range(2, int(m ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, m + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Grundy(number) = total number of prime factors with multiplicity, Ω(number).
    nim_xor = 0
    for x in A:
        cnt = 0
        while x > 1:
            cnt += 1
            x //= spf[x]
        nim_xor ^= cnt

    sys.stdout.write("Anna\n" if nim_xor != 0 else "Bruno\n")


if __name__ == "__main__":
    main()

