import sys


def main() -> None:
    input = sys.stdin.readline

    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a - 1, b - 1, c)

    queries = []
    closed_final = [False] * M

    for _ in range(Q):
        parts = list(map(int, input().split()))
        if parts[0] == 1:
            idx = parts[1] - 1
            queries.append((1, idx, -1))
            closed_final[idx] = True
        else:
            x, y = parts[1] - 1, parts[2] - 1
            queries.append((2, x, y))

    INF = 10**30
    n = N
    rng = range(n)

    # Graph state after all closures have been applied.
    dist = [[INF] * n for _ in rng]
    for i in rng:
        dist[i][i] = 0

    for i, (u, v, w) in enumerate(edges):
        if not closed_final[i]:
            dist[u][v] = w
            dist[v][u] = w

    # All-pairs shortest paths for final state.
    for k in rng:
        dk = dist[k]
        for i in rng:
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            base = dik
            for j in rng:
                nd = base + dk[j]
                if nd < di[j]:
                    di[j] = nd

    ans_rev = []

    # Reverse process: closure becomes insertion.
    for t, x, y in reversed(queries):
        if t == 2:
            d = dist[x][y]
            ans_rev.append(-1 if d >= INF else d)
            continue

        # Re-open edge x
        u, v, w = edges[x]

        # Snapshot distances before this insertion.
        du = [dist[a][u] for a in rng]
        dv = [dist[a][v] for a in rng]
        ub = dist[u][:]
        vb = dist[v][:]

        for a in rng:
            au = du[a]
            av = dv[a]
            if au == INF and av == INF:
                continue
            row = dist[a]

            if au != INF:
                base1 = au + w
                if av != INF:
                    base2 = av + w
                    for b in rng:
                        cand1 = base1 + vb[b]  # a -> u ->(w)-> v -> b
                        cand2 = base2 + ub[b]  # a -> v ->(w)-> u -> b
                        cand = cand1 if cand1 < cand2 else cand2
                        if cand < row[b]:
                            row[b] = cand
                else:
                    for b in rng:
                        cand = base1 + vb[b]
                        if cand < row[b]:
                            row[b] = cand
            else:
                base2 = av + w
                for b in rng:
                    cand = base2 + ub[b]
                    if cand < row[b]:
                        row[b] = cand

    sys.stdout.write("\n".join(map(str, reversed(ans_rev))))


