class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        # Binomial coefficients C[n][r] for 0 <= n,r <= L
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for n in range(L + 1):
            C[n][0] = C[n][n] = 1
            for r in range(1, n):
                C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

        # g[c] = number of popcount-operations needed to reduce c to 1
        # for c in [1..L]
        INF = 10**9
        g = [INF] * (L + 1)
        g[1] = 0
        for c in range(2, L + 1):
            g[c] = 1 + g[c.bit_count()]

        # For x with popcount(x)=c, x is k-reducible iff g[c] <= k-1
        good = [False] * (L + 1)
        for c in range(1, L + 1):
            if g[c] <= k - 1:
                good[c] = True

        # Count numbers y with exactly `target` set bits and y < n (n given by s)
        def count_lt_with_ones(target: int) -> int:
            if target < 0 or target > L:
                return 0
            ans = 0
            ones_used = 0
            rem = L
            for ch in s:
                rem -= 1
                if ch == '1':
                    need = target - ones_used
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD
                    ones_used += 1
                    if ones_used > target:
                        break
            return ans

        ans = 0
        for c in range(1, L + 1):
            if good[c]:
                ans = (ans + count_lt_with_ones(c)) % MOD

        return ans

