import sys
MOD=998244353

def count_onto(len_s, alph):
    if len_s < alph:
        return 0
    res = 0
    from math import comb
    for j in range(alph + 1):
        term = comb(alph, j) * pow(alph - j, len_s, MOD)
        if j & 1:
            res = (res - term) % MOD
        else:
            res = (res + term) % MOD
    return res

def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    X = list(map(int, input().split()))

    onto = [0] * (N + 1)
    for l in range(N + 1):
        onto[l] = count_onto(l, K - 1)

    arches = M - 1
    dp = [[0] * (N + 1) for _ in range(arches + 1)]
    dp[0][0] = 1

    for i in range(arches):
        for s in range(N + 1):
            cur = dp[i][s]
            if not cur:
                continue
            max_li = N - s
            for li in range(K, max_li + 1):
                ways = onto[li - 1]
                if ways:
                    dp[i + 1][s + li] = (dp[i + 1][s + li] + cur * ways) % MOD

    ans = 0
    for s in range(N + 1):
        ways_arch = dp[arches][s]
        if not ways_arch:
            continue
        r = N - s
        ways_tail = onto[r]
        ans = (ans + ways_arch * ways_tail) % MOD

    print(ans % MOD)

