import random

def construct(N,P,Q):
    ppos=[0]*(N+1)
    for k,r in enumerate(P,1): ppos[r]=k
    # thresholds 0..N, drop x=0
    vals=list(range(1,N+1)) # include 1..N ; excludes0
    # U_t for t in vals
    U={}
    for t in vals:
        s=['1' if ppos[i]>t else '0' for i in range(1,N+1)]
        U[t]=''.join(s)
    vals_sorted=sorted(vals,key=lambda t:U[t])
    t_of_col=[None]*(N+1)
    for k,col in enumerate(Q):
        t_of_col[col]=vals_sorted[k]
    A=[[None]*(N+1) for _ in range(N+1)]
    for k,r in enumerate(P,1):
        for j in range(1,N+1):
            A[r][j]='1' if t_of_col[j] < k else '0'
    rows=[''.join(A[i][1:]) for i in range(1,N+1)]
    return rows

