    N=len(rows)
    for a,b in zip(P,P[1:]):
        if not(rows[a-1] < rows[b-1]): return False
    cols=[''.join(rows[i][j] for i in range(N)) for j in range(N)]
    for a,b in zip(Q,Q[1:]):
        if not(cols[a-1] < cols[b-1]): return False
    return True

