                if turn==0:
                    if not win(t2|bj,a2,1-turn):return True
                else:
                    if not win(t2,a2|bj,1-turn):return True
        return False
    st=time.time();win(t_init,a_init,0);return time.time()-st,win.cache_info().currsize

