        def add(self,i,x):
            while i<=self.n:self.b[i]+=x;i+=i&-i
        def sum(self,i):
            s=0
            while i>0:s+=self.b[i];i-=i&-i
            return s
    fw=FW(N);inv=0
    for i,v in enumerate(P):
        inv += i-fw.sum(v); fw.add(v,1)
    M=N-K+1
    fw2=FW(N);w=0;sz=0
    for i in range(K):
        v=P[i]; w += sz-fw2.sum(v); fw2.add(v,1); sz+=1
    sw=w
    for s in range(1,M):
        x=P[s-1]; w -= fw2.sum(x-1); fw2.add(x,-1); sz-=1
        y=P[s+K-1]; w += sz-fw2.sum(y); fw2.add(y,1); sz+=1
        sw += w
    return Fraction(inv,1)+Fraction(K*(K-1),4)-Fraction(sw,M)

def brute(N,K,P):
    M=N-K+1
    E=Fraction(0,1)
    for s in range(M):
        arr=P[:]
        seg=P[s:s+K]
        tot=0
        cnt=0
        for perm in itertools.permutations(seg):
            cnt+=1
            b=arr[:]
            b[s:s+K]=perm
            inv=0
            for i in range(N):
                for j in range(i+1,N):
                    inv += b[i]>b[j]
            tot+=inv
        E += Fraction(tot,cnt)
    return E/M

