import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i
    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s
    def lower_bound(self, x):
        i = 0
        bitmask = 1 << (self.n.bit_length() - 1)
        while bitmask:
            ni = i + bitmask
            if ni <= self.n and self.bit[ni] < x:
                x -= self.bit[ni]
                i = ni
            bitmask >>= 1
        return i + 1

