class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)
        INF = 10**9

        def build_next(token: str):
            L = len(token)
            if L == 0:
                return None, 0  # Empty token matches at every position.

            # KMP prefix-function for token.
            pi = [0] * L
            j = 0
            for i in range(1, L):
                while j and token[i] != token[j]:
                    j = pi[j - 1]
                if token[i] == token[j]:
                    j += 1
                    pi[i] = j

            # Mark all start indices where token occurs in s.
            occ = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != token[j]:
                    j = pi[j - 1]
                if ch == token[j]:
                    j += 1
                    if j == L:
                        occ[i - L + 1] = True
                        j = pi[j - 1]

            # next_pos[i] = smallest position >= i where token starts, else INF.
            next_pos = [INF] * (n + 2)
            for i in range(n, -1, -1):
                if i <= n - L and occ[i]:
                    next_pos[i] = i
                else:
                    next_pos[i] = next_pos[i + 1]
            return next_pos, L

        next_a, la = build_next(a)
        next_b, lb = build_next(b)
        next_c, lc = build_next(c)

        def get_next(next_arr, pos):
            if pos > n:
                return INF
            if next_arr is None:  # empty token
                return pos
            return next_arr[pos]

        starts = range(n + 1) if la == 0 else range(0, n - la + 1)
        ans = INF

        for i in starts:
            # If a is non-empty, substring must start exactly at an occurrence of a.
            if la > 0 and get_next(next_a, i) != i:
                continue

            sb = get_next(next_b, i + la)
            if sb >= INF:
                continue

            sc = get_next(next_c, sb + lb)
            if sc >= INF:
                continue

            ans = min(ans, sc + lc - i)

        return -1 if ans >= INF else ans

