import sys

def feasible(x, z, t):
    m = len(x)
    r = len(z)
    if m < r:
        return False

    L = [0] * m
    U = [0] * m

    j = 0
    for i, a in enumerate(x):
        while j < r and z[j] < a - t:
            j += 1
        L[i] = j

    j = 0
    for i, a in enumerate(x):
        while j < r and z[j] <= a + t:
            j += 1
        U[i] = j - 1
        if U[i] < L[i]:
            return False

    # Ensure every target index can be assigned to at least one piece in order.
    i = 0
    for target_idx in range(r):
        if i < target_idx:
            i = target_idx
        while i < m and (L[i] > target_idx or U[i] < target_idx):
            i += 1
        if i == m:
            return False
        i += 1

    # Ensure there exists a nondecreasing full assignment for all pieces.
    cur = 0
    for i in range(m):
        if cur < L[i]:
            cur = L[i]
        if cur > U[i]:
            return False

    return True


def solve_case(n, a, b):
    x = [i + 1 for i, ch in enumerate(a) if ch == '1']
    z = [i + 1 for i, ch in enumerate(b) if ch == '1']

    if len(x) < len(z):
        return -1

    lo, hi = 0, n
    if not feasible(x, z, hi):
        return -1

    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(x, z, mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


