from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = 10**30
        min_prefix = [INF] * k
        min_prefix[0] = 0  # prefix sum at index 0

        prefix_sum = 0
        best = -INF

        for i, x in enumerate(nums, 1):
            prefix_sum += x
            r = i % k

            prev_min = min_prefix[r]
            if prev_min != INF:
                candidate = prefix_sum - prev_min
                if candidate > best:
                    best = candidate

            if prefix_sum < prev_min:
                min_prefix[r] = prefix_sum

        return best

