import sys


def sieve(n: int):
    if n < 2:
        return []
    is_prime = bytearray(b"\x01") * (n + 1)
    is_prime[0:2] = b"\x00\x00"
    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:n + 1:p] = b"\x00" * (((n - start) // p) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]


def main():
    N_line = sys.stdin.readline().strip()
    if not N_line:
        return
    N = int(N_line)

    # For numbers of form p^2 q^2, we need p*q <= sqrt(N)
    M = int(N ** 0.5)
    primes = sieve(M)

    ans = 0

    # 1) n = p^8
    for p in primes:
        if p ** 8 <= N:
            ans += 1
        else:
            break

    # 2) n = p^2 q^2 (p < q), equivalently p*q <= M
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > M:
            j -= 1
        if j <= i:
            break
        ans += (j - i)

    print(ans)


if __name__ == "__main__":
