        for j in range(i+1, N):
            c = next(it)
            A[i][j] = A[j][i] = c

    ans = 10**30
    idx = list(range(N))
    for p in permutations(idx):
        cost = 0
        # p[i] = vertex in H corresponding to vertex i in G
        for i in range(N-1):
            pi = p[i]
            Gi = G[i]
            for j in range(i+1, N):
                if Gi[j] != H[pi][p[j]]:
                    cost += A[pi][p[j]]
                    if cost >= ans:
                        break
            if cost >= ans:
                break
        if cost < ans:
            ans = cost

    print(ans)

