class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        best = 0
        total = 0
        # For each unit move t -> t+1 (t from 0 to n-2),
        # we can use any departure index <= t, so the best possible
        # value contributed on this step is prefix maximum up to t.
        for i in range(len(nums) - 1):
            if nums[i] > best:
                best = nums[i]
            total += best
        return total

