class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # Already a Zero Array.
        if all(x == 0 for x in nums):
            return 0

        # bits[i]: bit-sum DP for index i using processed prefix of queries.
        # bit s is 1 if sum s is achievable at index i.
        bits = [1] * n
        masks = [(1 << (x + 1)) - 1 for x in nums]  # cap sums to nums[i]

        def all_reachable() -> bool:
            for i, target in enumerate(nums):
                if ((bits[i] >> target) & 1) == 0:
                    return False
            return True

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                b = bits[i]
                bits[i] = b | ((b << val) & masks[i])

            if all_reachable():
                return k

        return -1

