from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        d = len(str(n))
        lower = 10 ** (d - 1)
        upper = 10 ** d

        # Prime sieve in [0, upper)
        is_prime = [True] * upper
        if upper > 0:
            is_prime[0] = False
        if upper > 1:
            is_prime[1] = False

        p = 2
        while p * p < upper:
            if is_prime[p]:
                for x in range(p * p, upper, p):
                    is_prime[x] = False
            p += 1

        # n must stay non-prime at all times, including start and finish
        if is_prime[n] or is_prime[m]:
            return -1

        INF = 10**30
        dist = [INF] * upper
        dist[n] = n  # cost includes initial value

        pq = [(n, n)]  # (total_cost, current_value)

        while pq:
            cost, u = heappop(pq)
            if cost != dist[u]:
                continue
            if u == m:
                return cost

            for i in range(d):
                place = 10 ** i
                digit = (u // place) % 10

                # Increase this digit
                if digit < 9:
                    v = u + place
                    if v < upper and not is_prime[v]:
                        nc = cost + v
                        if nc < dist[v]:
                            dist[v] = nc
                            heappush(pq, (nc, v))

                # Decrease this digit
                if i == d - 1:  # most significant digit must not become 0
                    if digit > 1:
                        v = u - place
                        if v >= lower and not is_prime[v]:
                            nc = cost + v
                            if nc < dist[v]:
                                dist[v] = nc
                                heappush(pq, (nc, v))
                else:
                    if digit > 0:
                        v = u - place
                        if v >= lower and not is_prime[v]:
                            nc = cost + v
                            if nc < dist[v]:
                                dist[v] = nc
                                heappush(pq, (nc, v))

        return -1

