from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        MASK = (1 << 64) - 1
        B = 911382323

        pref = [0] * (n + 1)
        pows = [1] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = (pref[i] * B + (x + 1)) & MASK
            pows[i + 1] = (pows[i] * B) & MASK

        ans = 0
        for i in range(1, n - 1):
            # Condition A: nums1 is prefix of nums2.
            # For fixed i, this only depends on whether nums[0:i] == nums[i:2*i],
            # and then all j >= 2*i satisfy A.
            a_possible = False
            if 2 * i <= n:
                h0 = pref[i]  # hash(0, i)
                hi = (pref[2 * i] - (pref[i] * pows[i] & MASK)) & MASK  # hash(i, 2i)
                a_possible = (h0 == hi)

            if a_possible:
                start_a = max(i + 1, 2 * i)
                if start_a <= n - 1:
                    ans += n - start_a

            # Condition B requires len2 <= len3, i.e. j <= (n + i)//2.
            ub = (n + i) // 2
            if ub < i + 1:
                continue

            # To avoid double-counting with A, only check B where A is false.
            if a_possible:
                end = min(ub, 2 * i - 1)  # here j < 2i => A false
                for j in range(i + 1, end + 1):
                    L = j - i
                    h1 = (pref[j] - (pref[i] * pows[L] & MASK)) & MASK      # hash(i, j)
                    h2 = (pref[j + L] - (pref[j] * pows[L] & MASK)) & MASK  # hash(j, j+L)
                    if h1 == h2:
                        ans += 1
            else:
                for j in range(i + 1, ub + 1):
                    L = j - i
                    h1 = (pref[j] - (pref[i] * pows[L] & MASK)) & MASK
                    h2 = (pref[j + L] - (pref[j] * pows[L] & MASK)) & MASK
                    if h1 == h2:
                        ans += 1

        return ans

