import itertools,random

def brute(A):
    n=len(A)
    best=-10**18
    # enumerate operation choices bit 1 push 0 pop with validity
    def dfs(i,stack,sumv):
        nonlocal best
        if i==n:
            best=max(best,sumv)
            return
        # push
        stack.append(A[i]); dfs(i+1,stack,sumv+A[i]); stack.pop()
        if stack:
            x=stack.pop(); dfs(i+1,stack,sumv-x); stack.append(x)
    dfs(0,[],0)
    return best

def fast(A):
