from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold >= 1, so we can always prune to out-degree <= 1 if reachability holds.
        # Thus we only need the minimum W such that using edges with weight <= W,
        # every node can reach node 0.

        rev = [[] for _ in range(n)]  # reversed edges: v -> (u, w) for original u -> v
        max_w = 0
        for u, v, w in edges:
            rev[v].append((u, w))
            if w > max_w:
                max_w = w

        def feasible(limit: int) -> bool:
            # In reversed graph, check if 0 can reach all nodes via edges with weight <= limit.
            vis = [False] * n
            q = deque([0])
            vis[0] = True
            seen = 1

            while q:
                x = q.popleft()
                for pre, w in rev[x]:
                    if w <= limit and not vis[pre]:
                        vis[pre] = True
                        seen += 1
                        q.append(pre)
            return seen == n

        # If impossible even with all edges, answer is -1.
        if not feasible(max_w):
            return -1

        lo, hi = 1, max_w
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

