from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**30

        # dp[a][b] = minimum cost after processing pairs [0..i],
        # where house i has color a and house (n-1-i) has color b.
        dp = [[INF] * 3 for _ in range(3)]

        # Initialize pair i = 0: houses 0 and n-1 must have different colors.
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        # Process inward pairs.
        for i in range(1, m):
            li, ri = i, n - 1 - i
            ndp = [[INF] * 3 for _ in range(3)]

            for a in range(3):
                for b in range(3):
                    if a == b:  # equidistant houses must differ
                        continue

                    add = cost[li][a] + cost[ri][b]
                    best_prev = INF

                    # Adjacent constraints:
                    # left side: color(i) != color(i-1)  => a != pa
                    # right side: color(ri) != color(ri+1) => b != pb
                    for pa in range(3):
                        if pa == a:
                            continue
                        row = dp[pa]
                        for pb in range(3):
                            if pb == b:
                                continue
                            if row[pb] < best_prev:
                                best_prev = row[pb]

                    ndp[a][b] = best_prev + add

            dp = ndp

        return min(min(row) for row in dp)

