class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base_active = s.count('1')
        t = '1' + s + '1'

        # Run-length encoding of augmented string t
        runs = []  # (char, length)
        i, n = 0, len(t)
        while i < n:
            j = i
            ch = t[i]
            while j < n and t[j] == ch:
                j += 1
            runs.append((ch, j - i))
            i = j

        # If we choose an internal 1-run surrounded by 0-runs, and perform the trade,
        # net gain equals left_zero_len + right_zero_len.
        best_gain = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1' and runs[k - 1][0] == '0' and runs[k + 1][0] == '0':
                gain = runs[k - 1][1] + runs[k + 1][1]
                if gain > best_gain:
                    best_gain = gain

        return base_active + best_gain

