class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vid = {'a': 0, 'e': 1, 'i': 2, 'o': 3, 'u': 4}

        def at_most(K: int) -> int:
            if K < 0:
                return 0

            last = [-1] * 5   # last positions of a,e,i,o,u
            left = 0
            consonants = 0
            total = 0

            for right, ch in enumerate(word):
                if ch in vid:
                    last[vid[ch]] = right
                else:
                    consonants += 1

                while consonants > K:
                    if word[left] not in vid:
                        consonants -= 1
                    left += 1

                # If all vowels have appeared, valid starts are left..min(last)
                if -1 not in last:
                    min_last = min(last)
                    if min_last >= left:
                        total += min_last - left + 1

            return total

        # exactly k = at most k - at most (k-1)
        return at_most(k) - at_most(k - 1)

