from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = [tuple(p) for p in points]
        pset = set(pts)
        n = len(pts)
        best = -1

        for i in range(n):
            x1, y1 = pts[i]
            for j in range(i + 1, n):
                x2, y2 = pts[j]

                # Need opposite corners (not same row/column).
                if x1 == x2 or y1 == y2:
                    continue

                # The other two corners must exist.
                if (x1, y2) not in pset or (x2, y1) not in pset:
                    continue

                minx, maxx = (x1, x2) if x1 < x2 else (x2, x1)
                miny, maxy = (y1, y2) if y1 < y2 else (y2, y1)

                # Valid only if no extra point lies inside or on border.
                # Since corners are present, exactly 4 points can be in the closed rectangle.
                count_in_closed_rect = 0
                for x, y in pts:
                    if minx <= x <= maxx and miny <= y <= maxy:
                        count_in_closed_rect += 1
                        if count_in_closed_rect > 4:
                            break

                if count_in_closed_rect == 4:
                    area = (maxx - minx) * (maxy - miny)
                    if area > best:
                        best = area

        return best

